import * as React from "react";
import {
  Animated,
  PanResponder,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { useTheme } from "@/components/native/theme";

export type SliderProps = {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  onValueChange?: (value: number) => void;
  /** Fires once when the user lets go. */
  onSlidingComplete?: (value: number) => void;
  /** Show a floating value bubble while dragging. */
  showValue?: boolean;
  formatValue?: (value: number) => string;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
};

const THUMB = 26;

export function Slider({
  value,
  defaultValue = 0,
  min = 0,
  max = 100,
  step = 1,
  onValueChange,
  onSlidingComplete,
  showValue = true,
  formatValue = (v) => String(v),
  disabled,
  style,
}: SliderProps) {
  const { colors, shadow } = useTheme();
  const [inner, setInner] = React.useState(defaultValue);
  const current = value ?? inner;
  const [width, setWidth] = React.useState(0);
  const [dragging, setDragging] = React.useState(false);
  const bubble = React.useRef(new Animated.Value(0)).current;
  const startX = React.useRef(0);
  const latest = React.useRef(current);
  latest.current = current;

  const range = max - min || 1;
  const ratio = (current - min) / range;
  const usable = Math.max(width - THUMB, 0);

  const setFromX = React.useCallback(
    (x: number) => {
      const r = Math.min(Math.max(x / (usable || 1), 0), 1);
      const raw = min + r * range;
      const next = Math.round(raw / step) * step;
      const clamped = Math.min(Math.max(Number(next.toFixed(6)), min), max);
      if (clamped !== latest.current) {
        latest.current = clamped;
        if (value === undefined) setInner(clamped);
        onValueChange?.(clamped);
      }
    },
    [usable, min, range, step, max, value, onValueChange],
  );

  const showBubble = (v: number) =>
    Animated.spring(bubble, {
      toValue: v,
      useNativeDriver: false,
      speed: 30,
      bounciness: 8,
    }).start();

  const pan = React.useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !disabled,
        onMoveShouldSetPanResponder: () => !disabled,
        onPanResponderTerminationRequest: () => false,
        onPanResponderGrant: (e) => {
          startX.current = e.nativeEvent.locationX - THUMB / 2;
          setFromX(startX.current);
          setDragging(true);
          showBubble(1);
        },
        onPanResponderMove: (_, g) => setFromX(startX.current + g.dx),
        onPanResponderRelease: () => {
          setDragging(false);
          showBubble(0);
          onSlidingComplete?.(latest.current);
        },
        onPanResponderTerminate: () => {
          setDragging(false);
          showBubble(0);
        },
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [disabled, setFromX, onSlidingComplete],
  );

  return (
    <View
      onLayout={(e: LayoutChangeEvent) => setWidth(e.nativeEvent.layout.width)}
      accessibilityRole="adjustable"
      accessibilityValue={{ min, max, now: current }}
      accessibilityActions={[{ name: "increment" }, { name: "decrement" }]}
      onAccessibilityAction={(e) => {
        const delta = e.nativeEvent.actionName === "increment" ? step : -step;
        const next = Math.min(Math.max(current + delta, min), max);
        if (value === undefined) setInner(next);
        onValueChange?.(next);
      }}
      style={[styles.root, disabled && { opacity: 0.5 }, style]}
      {...pan.panHandlers}
    >
      <View pointerEvents="none" style={[styles.track, { backgroundColor: colors.muted }]}>
        <View
          style={[
            styles.fill,
            { backgroundColor: colors.primary, width: ratio * usable + THUMB / 2 },
          ]}
        />
      </View>
      <View
        pointerEvents="none"
        style={[
          styles.thumb,
          shadow(2),
          {
            left: ratio * usable,
            backgroundColor: "#ffffff",
            borderColor: colors.border,
            transform: [{ scale: dragging ? 1.08 : 1 }],
          },
        ]}
      />
      {showValue && (
        <Animated.View
          pointerEvents="none"
          style={[
            styles.bubble,
            {
              left: ratio * usable + THUMB / 2 - 24,
              backgroundColor: colors.primary,
              opacity: bubble,
              transform: [
                { translateY: bubble.interpolate({ inputRange: [0, 1], outputRange: [6, 0] }) },
                { scale: bubble.interpolate({ inputRange: [0, 1], outputRange: [0.7, 1] }) },
              ],
            },
          ]}
        >
          <Text style={[styles.bubbleText, { color: colors.primaryForeground }]}>
            {formatValue(current)}
          </Text>
        </Animated.View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  root: { height: THUMB + 12, justifyContent: "center" },
  // Children ignore touches so locationX is always relative to the root.
  track: { height: 6, borderRadius: 3, overflow: "hidden" },
  fill: { height: "100%", borderRadius: 3 },
  thumb: {
    position: "absolute",
    width: THUMB,
    height: THUMB,
    borderRadius: THUMB / 2,
    borderWidth: StyleSheet.hairlineWidth,
  },
  bubble: {
    position: "absolute",
    top: -30,
    width: 48,
    height: 28,
    borderRadius: 9,
    alignItems: "center",
    justifyContent: "center",
  },
  bubbleText: { fontSize: 13, fontWeight: "600", fontVariant: ["tabular-nums"] },
});

/**
 * Synapse UI Native: design tokens and theme.
 *
 * Every native component reads its colors from `useTheme()`. Wrap your app in
 * <ThemeProvider> to force a scheme or override colors; without it the system
 * color scheme is used.
 */
import * as React from "react";
import { Platform, useColorScheme, type ViewStyle } from "react-native";

export const palette = {
  light: {
    background: "#ffffff",
    foreground: "#0a0a0b",
    card: "#ffffff",
    cardForeground: "#0a0a0b",
    surface: "#fafafa",
    surfaceStrong: "#f4f4f5",
    muted: "#f4f4f5",
    mutedForeground: "#71717a",
    subtle: "#a1a1aa",
    border: "#e7e7ea",
    borderStrong: "#d4d4d8",
    input: "#e4e4e7",
    ring: "#a1a1aa",
    primary: "#18181b",
    primaryForeground: "#fafafa",
    secondary: "#f4f4f5",
    secondaryForeground: "#18181b",
    accent: "#f4f4f5",
    accentForeground: "#18181b",
    brand: "#2563eb",
    brandForeground: "#ffffff",
    brandSoft: "#eff4ff",
    success: "#16a34a",
    successSoft: "#ecfdf3",
    warning: "#d97706",
    warningSoft: "#fffaeb",
    destructive: "#dc2626",
    destructiveForeground: "#ffffff",
    destructiveSoft: "#fef2f2",
    overlay: "rgba(9, 9, 11, 0.42)",
    shadow: "#0a0a0b",
  },
  dark: {
    background: "#09090b",
    foreground: "#f4f4f5",
    card: "#111113",
    cardForeground: "#f4f4f5",
    surface: "#111113",
    surfaceStrong: "#18181b",
    muted: "#18181b",
    mutedForeground: "#a1a1aa",
    subtle: "#71717a",
    border: "#232327",
    borderStrong: "#2e2e33",
    input: "#27272a",
    ring: "#52525b",
    primary: "#f4f4f5",
    primaryForeground: "#09090b",
    secondary: "#1c1c1f",
    secondaryForeground: "#f4f4f5",
    accent: "#1f1f23",
    accentForeground: "#f4f4f5",
    brand: "#3b82f6",
    brandForeground: "#ffffff",
    brandSoft: "#172036",
    success: "#4ade80",
    successSoft: "#0f2418",
    warning: "#fbbf24",
    warningSoft: "#2a2110",
    destructive: "#f87171",
    destructiveForeground: "#0a0a0b",
    destructiveSoft: "#2a1414",
    overlay: "rgba(0, 0, 0, 0.62)",
    shadow: "#000000",
  },
};

export type ThemeColors = typeof palette.light;
export type ColorScheme = "light" | "dark";

export const radius = { xs: 6, sm: 8, md: 12, lg: 16, xl: 20, "2xl": 24, "3xl": 32, full: 9999 };

/** 4pt spacing scale: space(4) === 16. */
export const space = (n: number) => n * 4;

export const fontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
};

export const fontWeight = {
  regular: "400",
  medium: "500",
  semibold: "600",
  bold: "700",
} as const;

export const fontFamily = {
  mono: Platform.select({
    ios: "Menlo",
    android: "monospace",
    default: "ui-monospace, Menlo, monospace",
  }),
};

/** Animated: use the native driver everywhere except react-native-web. */
export const nativeDriver = Platform.OS !== "web";

/** Cross-platform elevation. Level 0–4. */
export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}
